const add = (type, line, detail) => issues.push({ type, line, detail });
const issues = [];
const num = v => Number(v ?? 0), tol = 0.01, wtol = 0.5;
const textLen = n => { try { return String($(n).first().json.text || '').trim().length; } catch (e) { return 0; } };

// Input guardrail: documents with (almost) no text, e.g. scanned images
if (textLen('Invoice Text') < 100) add('invoice_unreadable', null, 'Commercial invoice has no readable text (scanned or empty PDF?)');
if (textLen('Packing Text') < 100) add('packing_list_unreadable', null, 'Packing list has no readable text (scanned or empty PDF?)');

const invRaw = (() => { try { return $('Invoice Extractor').first().json.output; } catch (e) { return null; } })();
const plRaw = (() => { try { return $('Packing List Extractor').first().json.output; } catch (e) { return null; } })();
const inv = invRaw && Array.isArray(invRaw.items) ? invRaw : { items: [], total_value: null, origin_country: null, currency: null };
const pl = plRaw && Array.isArray(plRaw.items) ? plRaw : { items: [], total_net_weight_kg: null, total_gross_weight_kg: null };
if (!invRaw || !Array.isArray(invRaw.items)) add('invoice_not_extracted', null, 'Invoice data could not be extracted');
if (!plRaw || !Array.isArray(plRaw.items)) add('packing_list_not_extracted', null, 'Packing list data could not be extracted');

let co = null;
try { co = $('Origin Extractor').first().json.output ?? null; } catch (e) { co = null; }
let certUploaded = false;
try { certUploaded = !$('Origin Text').first().json.error; } catch (e) { certUploaded = false; }

if (inv.items.length !== pl.items.length)
  add('line_count', null, `Invoice has ${inv.items.length} lines, packing list has ${pl.items.length}`);

inv.items.forEach((it, i) => {
  const p = pl.items[i];
  if (p && num(it.quantity) !== num(p.quantity))
    add('quantity', it.line, `Invoice ${it.quantity}, packing list ${p.quantity}`);
  const calc = num(it.quantity) * num(it.unit_price);
  if (Math.abs(calc - num(it.line_total)) > tol)
    add('line_total', it.line, `${it.quantity} x ${it.unit_price} = ${calc.toFixed(2)}, invoice says ${it.line_total}`);
  if (p && num(p.net_weight_kg) > num(p.gross_weight_kg))
    add('weight', it.line, `Net ${p.net_weight_kg} kg above gross ${p.gross_weight_kg} kg`);
  ['description', 'quantity', 'line_total'].forEach(f => {
    if (it[f] === null || it[f] === undefined) add('missing', it.line, `Invoice line has no ${f}`);
  });
});

if (inv.items.length) {
  const sumV = inv.items.reduce((s, it) => s + num(it.line_total), 0);
  if (Math.abs(sumV - num(inv.total_value)) > tol)
    add('total_value', null, `Lines add up to ${sumV.toFixed(2)}, total is ${inv.total_value}`);
}
if (pl.items.length) {
  const sumN = pl.items.reduce((s, p) => s + num(p.net_weight_kg), 0);
  if (Math.abs(sumN - num(pl.total_net_weight_kg)) > wtol)
    add('total_net_weight', null, `Lines ${sumN} kg, total ${pl.total_net_weight_kg} kg`);
  const sumG = pl.items.reduce((s, p) => s + num(p.gross_weight_kg), 0);
  if (Math.abs(sumG - num(pl.total_gross_weight_kg)) > wtol)
    add('total_gross_weight', null, `Lines ${sumG} kg, total ${pl.total_gross_weight_kg} kg`);
}
if (co && co.origin_country && inv.origin_country && co.origin_country !== inv.origin_country)
  add('origin', null, `Invoice ${inv.origin_country}, certificate ${co.origin_country}`);
if (certUploaded && !co)
  add('certificate_unreadable', null, 'Certificate of origin was uploaded but could not be read');

// Injection guardrail result
let injection = false;
try { injection = $('Flag Injection').isExecuted && $('Flag Injection').first().json.injection_flag === true; } catch (e) { injection = false; }
if (injection)
  add('possible_prompt_injection', null, 'Document text contains instruction-like content; check the documents before use');

return [{ json: {
  shipment_id: $('Shipment Upload').first().json['Shipment ID'],
  invoice: inv, packing: pl, origin: co, consistency_issues: issues
} }];

const d = $input.first().json;
const items = d.invoice.items || [];
if (!items.length) {
  return [{ json: { line: 0, description: 'NO INVOICE LINES EXTRACTED', origin_country: d.invoice.origin_country || null } }];
}
return items.map(it => ({ json: {
  line: it.line,
  description: String(it.description).replace(/\n/g, ' '),
  origin_country: d.invoice.origin_country
} }));

